class Noeud:
    def __init__(self, valeur, suivant=None):
        self.valeur = valeur
        self.suivant = suivant

class ListeChainee:
    def __init__(self):
        self.tete = None

    def inserer_en_tete(self, valeur):
        self.tete = Noeud(valeur, self.tete)

    def vers_liste(self):
        valeurs = []
        n = self.tete
        while n is not None:
            valeurs.append(n.valeur)
            n = n.suivant
        return valeurs

