def equilibre(texte):
    paires = {')': '(', ']': '[', '}': '{'}
    pile = []
    for c in texte:
        if c in '([{':
            pile.append(c)
        elif c in paires:
            if not pile or pile.pop() != paires[c]:
                return False
    return len(pile) == 0

